import type { CanvasserSideCheckrStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';
import { InfoIcon, CircleAlertIcon } from 'lucide-vue-next';

interface AccountCheckerStatusEntry {
  label: string;
  icon: Component;
  variant: BadgeVariants;
  title: string;
  description: string;
}

export const accountCheckerStatuses: Record<CanvasserSideCheckrStatus, AccountCheckerStatusEntry> = {
  provide_information: {
    variant: 'warning',
    icon: CircleAlertIcon,
    label: 'Provide Information',
    title: 'Action required - Provide Information',
    description: 'Please provide the necessary information to complete your background check',
  },
  investigation_running: {
    variant: 'info',
    icon: InfoIcon,
    label: 'Check is Running',
    title: 'Background check is running',
    description: 'Your background check is being processed',
  },
  awaiting_review: {
    variant: 'info',
    icon: InfoIcon,
    label: 'Awaiting Review',
    title: 'Awaiting review from recruiter',
    description: 'Your background check is awaiting review from the recruiter',
  },
  decision_assigned: {
    variant: 'success',
    icon: InfoIcon,
    label: 'Finished',
    title: 'Background check is finished',
    description: 'Your background check is finished and the decision has been assigned',
  },
  invitation_expired: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Invitation Expired',
    title: 'Invitation expired',
    description: 'Your background check invitation has expired.',
  },
};

const defaultAccountCheckerStatus: AccountCheckerStatusEntry = {
  label: '',
  icon: InfoIcon,
  variant: 'default',
  title: '',
  description: '',
};

export function getAccountCheckerStatus(status: CanvasserSideCheckrStatus): AccountCheckerStatusEntry {
  return (
    accountCheckerStatuses[status] ?? { ...defaultAccountCheckerStatus, label: snakeCaseToCapitalizedCase(status) }
  );
}
