<template>
  <Card>
    <CardHeader class="flex flex-row items-center justify-between">
      <CardTitle class="p-0 text-lg font-semibold">Additional information</CardTitle>
      <NuxtLink v-if="!data" :to="{ name: 'account-canvasser-edit-application' }">
        <Button variant="outline">Add Information</Button>
      </NuxtLink>
    </CardHeader>
    <CardContent v-if="data" class="grid grid-cols-1 gap-6 sm:grid-cols-2">
      <div class="flex flex-col gap-3">
        <p class="text-sm font-semibold text-accent-muted">Address information</p>
        <div class="flex flex-col gap-6">
          <div v-for="item in addressInfo" :key="item.label">
            <LabeledValue
              :label="item.label"
              :value-class="item.label === 'Address' || item.label === 'City' ? 'break-words' : 'line-clamp-1'"
              >{{ item.value }}</LabeledValue
            >
          </div>
        </div>
      </div>

      <div class="flex flex-col gap-3">
        <p class="text-sm font-semibold text-accent-muted">Other information</p>
        <div class="flex flex-col gap-6">
          <div v-for="item in otherInfo" :key="item.label">
            <LabeledValue :label="item.label">
              <p v-if="item.label !== 'Equipment Confirmation'" class="font-base break-all">{{ item.value }}</p>
              <p v-else class="flex gap-2 items-center font-base break-all">
                <Check v-if="item.value" class="w-5 h-5 stroke-success-foreground" />
                <X v-else class="w-5 h-5 stroke-red-600" />
                <span>Has smartphone and ability to drive</span>
              </p>
            </LabeledValue>
          </div>
        </div>
      </div>
    </CardContent>
    <CardContent v-else>
      <p>No additional information provided</p>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { type GeneralInfo } from '~/client';
import { militaryServiceOptions } from '~/constants/account/militaryServiceOptions';
import { Check, X } from 'lucide-vue-next';

interface Props {
  data: GeneralInfo | null;
}

const props = defineProps<Props>();

const addressInfo = computed(() => {
  return [
    {
      label: 'Address',
      value: props.data?.address,
    },
    {
      label: 'City',
      value: props.data?.city,
    },
    {
      label: 'State',
      value: props.data?.state,
    },
    {
      label: 'ZIP',
      value: props.data?.zip_code,
    },
  ];
});

const otherInfo = computed(() => {
  return [
    {
      label: 'Date of Birth',
      value: props.data?.date_of_birth ? formatUTCDateString(props.data?.date_of_birth, 'MM/dd/yyyy') : '',
    },
    {
      label: 'Military Service',
      value: militaryServiceOptions.find((item) => item.value === props.data?.military_service)?.name,
    },
    {
      label: 'Equipment Confirmation',
      value: props.data?.equipment_confirmation,
    },
    {
      label: 'Referral Source',
      value: props.data?.referral_source,
    },
  ];
});
</script>

<style scoped lang="scss"></style>
