<template>
  <Dialog>
    <DialogTrigger as-child>
      <Badge :variant="getAccountCheckerStatus(status).variant" class="cursor-help">{{
        getAccountCheckerStatus(status).label
      }}</Badge>
    </DialogTrigger>
    <DialogContent class="rounded-lg max-w-5xl w-[95%] max-h-[90dvh] overflow-y-auto">
      <DialogTitle>Checkr Statuses</DialogTitle>
      <DialogDescription>
        <AppMarkdown :markdown="checkrStatusesDescription" />
      </DialogDescription>
    </DialogContent>
  </Dialog>
</template>
<script setup lang="ts">
import type { CanvasserSideCheckrStatus } from '~/client';
import { accountCheckerStatuses, getAccountCheckerStatus } from '~/constants/account/checkerStatuses';

defineProps<{ status: CanvasserSideCheckrStatus }>();
const checkrStatusesDescription =
  Object.entries(accountCheckerStatuses)
    .map(([key, value]) => {
      return `- **${value.label}**: ${value.title}. ${value.description}`;
    })
    .join('\n') +
  `
\nPlease visit the provider's website for more information.`;
</script>
